package com.facebook.react.common.build;

/**
 * Shim for an upstream packaging bug in the stripe_android Flutter plugin.
 *
 * flutter_stripe's Android module is generated by syncing Stripe's React Native
 * SDK (see its CHANGELOG: "Sync with Stripe React Native"). That sync leaves one
 * React-Native-only file in the plugin — NativeStripeSdkModuleSpec.java — which
 * imports com.facebook.react.common.build.ReactBuildConfig. The plugin declares
 * no React Native dependency, and its build.gradle compiles src/main/kotlin as a
 * Java source dir, so the class is compiled and the release build fails with
 * "package com.facebook.react.common.build does not exist".
 *
 * Present in stripe_android 13.1.0, 14.0.0 and 14.0.1 alike, so there is no
 * version to move to. StripeSdkModule.kt extends the generated spec, so the file
 * cannot simply be excluded either.
 *
 * The class is only read for two compile-time booleans that gate React Native's
 * own debug logging, which a Flutter app never reaches. Both are false in a
 * release build, matching what React Native itself would produce.
 *
 * DELETE THIS once flutter_stripe stops shipping the React Native spec file.
 * Wired into the stripe_android module by the subprojects block in
 * android/build.gradle.kts.
 */
public final class ReactBuildConfig {
    public static final boolean DEBUG = false;
    public static final boolean IS_INTERNAL_BUILD = false;

    private ReactBuildConfig() {}
}
